from rdh import story
READ17 = [story("Morning with Mom", "Phrasal verbs",
 "Mother: Dina, wake up! It is six o'clock. Dina: I am awake, Mom. I get up now. Mother: Turn off the alarm and put on your uniform. Dina: OK. Where are my shoes? Mother: They are by the door. Put them on and come to breakfast. Dina: Thank you, Mom. I sit down and eat now.",
 "Mother: Dina, bangun! Sudah pukul enam. Dina: Aku sudah terbangun, Bu. Aku bangun dari tempat tidur sekarang. Mother: Matikan alarmnya dan pakai seragammu. Dina: Baik. Di mana sepatuku? Mother: Ada di dekat pintu. Pakai dan datang sarapan. Dina: Terima kasih, Bu. Aku duduk dan makan sekarang.",
 ("What does Mother ask Dina to do with the alarm?", "Turn it off", "Turn it on", "Put it on", "Take it off", "Mother: \"Turn off the alarm\"."),
 ("Put on them and come to breakfast.", "Turn off the alarm and put on your uniform.", "Put them on and come to breakfast.", "Mother says, wake up!", "Kata ganti (them) harus di tengah: put them on."),
 ('Choose the correct word: "Put your shoes ___ and come to breakfast."', "on", "off", "up", "down", "Put on = memakai."),
 [("Matikan alarmnya.", "Turn ___ the alarm.", "off", "Turn off = mematikan."),
  ("Aku duduk dan makan sekarang.", "I sit ___ and eat now.", "down", "Sit down = duduk.")],
 ("Pakai seragammu.", "Put on your uniform.", "off", "Put on = memakai."))]
